const S=[{s:0.05,p:0},{s:0.12,p:0},{s:0.20,p:0},{s:0.28,p:0},{s:0.35,p:0},{s:0.45,p:0},{s:0.55,p:1},{s:0.62,p:0},{s:0.78,p:0},{s:0.85,p:1}];
export function evaluate({inputs}){
  const c=inputs.cutoff;
  const X=sdk.linear([0,1],[80,880]);
  const o=[];
  let tp=0,fp=0,fn=0,tn=0;
  o.push(sdk.line('axis',80,195,880,195));
  o.push(sdk.text('t0',80,215,'0',{align:'middle'}));
  o.push(sdk.text('t1',880,215,'1',{align:'middle'}));
  S.forEach((d,i)=>{
    const pred=d.s>=c-1e-9;
    let tag,role;
    if(d.p&&pred){tp++;tag='TP';role='success';}
    else if(d.p&&!pred){fn++;tag='MISS';role='warning';}
    else if(!d.p&&pred){fp++;tag='FA';role='warning';}
    else{tn++;tag='TN';role='neutral';}
    const x=X(d.s);
    const lbl=(d.p?'+':'')+sdk.format(d.s,2).replace(/^0/,'');
    o.push(sdk.circle('d'+i,x,150,d.p?46:32,{text:lbl,role:role}));
    o.push(sdk.text('g'+i,x,112,tag,{align:'middle',role:role}));
  });
  const cx=X(c);
  o.push(sdk.line('cut',cx,85,cx,190,{role:'prediction'}));
  o.push(sdk.text('cutl',sdk.clamp(cx,60,900),72,'cutoff '+sdk.format(c,2),{align:'middle',role:'prediction'}));
  o.push(sdk.text('leg',80,248,'Big dots marked + are the 2 actual positives. Score >= cutoff: predicted positive. FA = false alarm, MISS = missed positive.'));
  const act=[];
  if(fn>0)act.push([0,1]);
  if(fp>0)act.push([1,0]);
  o.push(...sdk.grid('cm',{x:60,y:280,w:400,h:180,rows:[['TP '+tp,'Missed '+fn],['False alarm '+fp,'TN '+tn]],rowLabels:['Actual +','Actual -'],columnLabels:['Predicted +','Predicted -'],active:act}));
  const pp=tp+fp;
  const prec=pp>0?tp/pp:null;
  const rec=tp/(tp+fn);
  const acc=(tp+tn)/10;
  o.push(sdk.text('mp',520,310,'Precision = TP/(TP+FP) = '+(pp>0?tp+'/'+pp+' = '+sdk.format(prec,2):'undefined (nothing predicted +)')));
  o.push(sdk.text('mr',520,355,'Recall = TP/(TP+Missed) = '+tp+'/'+(tp+fn)+' = '+sdk.format(rec,2)));
  o.push(sdk.text('ma',520,400,'Accuracy = (TP+TN)/10 = '+(tp+tn)+'/10 = '+sdk.format(acc,2)));
  let note;
  if(rec<1) note='Accuracy is still '+Math.round(acc*100)+'% while '+fn+' of 2 positives are missed: 8 negatives dominate.';
  else note='Both positives caught, at the cost of '+fp+' false alarm'+(fp===1?'':'s')+'. Raise the cutoff to trade.';
  o.push(sdk.text('note',60,500,note,{role:'tutor'}));
  const q={tp:tp,fp:fp,fn:fn,tn:tn,recall:rec,accuracy:acc};
  if(prec!==null)q.precision=prec;
  return {frame:sdk.frame(o,{width:960,height:540,readouts:[{id:'tp',value:tp},{id:'fp',value:fp},{id:'fn',value:fn},{id:'tn',value:tn},{id:'recall',value:rec},{id:'accuracy',value:acc}]}),quantities:q};
}

